"""Build the review-only revision 71 patch from the exact revision 70 Git object."""
import copy, difflib, hashlib, json, pathlib, subprocess
BASE = '56f185e07dfafe5533df617ec1dad473ecb63f68'
OUT = pathlib.Path(__file__).resolve().parent
raw = subprocess.check_output(['git', 'show', BASE + ':specs/requirements.json']).decode()
before = json.loads(raw)
assert before['revision'] == 70
after = copy.deepcopy(before)
rows = {r['id']: r for r in after['requirements']}
reasons = {}
def replace(rid, field, old, new, reason):
    assert rows[rid]['status'] == 'approved'
    assert old in rows[rid][field], (rid, field, old)
    rows[rid][field] = rows[rid][field].replace(old, new)
    reasons[rid] = reason
def setfield(rid, field, value, reason):
    assert rows[rid]['status'] == 'approved'
    rows[rid][field] = value
    reasons[rid] = reason
def native(rid):
    for field in ['statement', 'measurement']:
        if 'USDG' in rows[rid][field]:
            replace(rid, field, 'USDG', 'native ETH', 'The selected quote and settlement asset is native ETH; preserve the existing economic rule.')

native('REQ-provider-binding-1')
for rid in ['REQ-canonical-market-1','REQ-canonical-market-4','REQ-canonical-market-5','REQ-fee-accounting-1','REQ-fee-accounting-4','REQ-fee-accounting-6','REQ-fee-accounting-7','REQ-canonical-market-7']:
    native(rid)
setfield('REQ-canonical-market-3','statement','The canonical native ETH/HKMN PoolKey uses Currency.wrap(address(0)) as currency0 and the nonzero final HKMN address as currency1. Internal native asset identity is {chainId: "4663", assetId: "native", decimals: 18}; zero-address encoding is confined to protocol boundaries. Display notation never determines ordering.','Native currency has one valid order, not two token-address permutations.')
setfield('REQ-canonical-market-3','measurement','The four buy/sell and exact-input/exact-output combinations pass with native currency0; swapped order, nonzero quote currency, wrong HKMN, and foreign PoolKey fields refuse without liability mutation.','Native currency has one valid order, not two token-address permutations.')
