for rid in ['REQ-fee-accounting-6', 'REQ-fee-accounting-7', 'REQ-canonical-market-7']:
    for field in ['statement', 'measurement']:
        rows[rid][field] = rows[rid][field].replace('smallest native ETH units', 'wei').replace('smallest native ETH unit', 'wei').replace('atomic native ETH', 'wei')

after['revision'] = 71
# Match the baseline serialization exactly; fail rather than creating unrelated formatting churn.
enc = next((ascii_mode for ascii_mode in [False, True] if json.dumps(before, indent=2, ensure_ascii=ascii_mode)+'\n' == raw), None)
assert enc is not None, 'baseline JSON serialization changed'
new = json.dumps(after, indent=2, ensure_ascii=enc)+'\n'
changed = [r['id'] for a,r in zip(before['requirements'],after['requirements']) if a != r]
assert set(changed) == set(reasons)
assert rows['REQ-transaction-policy-1'] == next(r for r in before['requirements'] if r['id']=='REQ-transaction-policy-1')
for rid in ['REQ-provider-binding-2','REQ-release-evidence-4','REQ-phase-boundary-1']:
    assert rows[rid] == next(r for r in before['requirements'] if r['id']==rid)
patch = ''.join(difflib.unified_diff(raw.splitlines(True),new.splitlines(True),fromfile='a/specs/requirements.json',tofile='b/specs/requirements.json'))
(OUT/'revision-71.patch').write_text(patch)
manifest = {'schema':'hookemon.native-eth-interface-proposal.v1','status':'PROPOSED_NOT_AUTHORITATIVE','baseCommit':BASE,'baseRequirementsRevision':70,'baseRequirementsSha256':hashlib.sha256(raw.encode()).hexdigest(),'proposedRequirementsRevision':71,'proposedRequirementsSha256':hashlib.sha256(new.encode()).hexdigest(),'patchSha256':hashlib.sha256(patch.encode()).hexdigest(),'changes':[{'requirementId':rid,'rationale':reasons[rid]} for rid in changed],'unchangedCollectorRequirement':'REQ-transaction-policy-1','preservedHistoricalRequirements':['REQ-provider-binding-2','REQ-release-evidence-4','REQ-phase-boundary-1']}
